const since = Math.floor(Date.now() / 1000) - (14 * 24 * 60 * 60);
const queries = [
  { query: 'customer feedback', query_type: 'customer_feedback' },
  { query: 'survey tool', query_type: 'survey_tool' },
  { query: 'nps csat', query_type: 'nps_csat' },
  { query: 'qualtrics alternative', query_type: 'qualtrics_alternative' },
  { query: 'delighted alternative', query_type: 'delighted_alternative' },
  { query: 'typeform alternative', query_type: 'typeform_alternative' },
  { query: 'uservoice alternative', query_type: 'uservoice_alternative' },
  { query: 'in app feedback', query_type: 'in_app_feedback' },
];

return queries.map(({ query, query_type }) => ({
  json: {
    url: 'https://hn.algolia.com/api/v1/search_by_date?'
      + 'query=' + encodeURIComponent(query)
      + '&tags=story'
      + '&numericFilters=' + encodeURIComponent('created_at_i>' + since)
      + '&hitsPerPage=20',
    query_type,
  },
}));

const items = $input.all();
const posts = [];
for (const item of items) {
  const hits = item.json && item.json.hits ? item.json.hits : [];
  for (const hit of hits) {
    if (!hit.title) continue;
    posts.push({
      json: {
        title: hit.title || '',
        body: hit.story_text || hit.comment_text || '',
        url: 'https://news.ycombinator.com/item?id=' + hit.objectID,
        author: hit.author || '',
        subreddit: '',
        source: 'HackerNews',
        objectID: hit.objectID || '',
        points: hit.points || 0,
        num_comments: hit.num_comments || 0
      }
    });
  }
}
return posts;

const cx_query = `query { posts(order: NEWEST, topic: "customer-success", first: 20) { edges { node { id name tagline description url votesCount commentsCount createdAt } } } }`;
const competitor_query = `query { posts(order: NEWEST, first: 20) { edges { node { id name tagline description url votesCount createdAt comments(first: 5, order: VOTES) { edges { node { body } } } } } } }`;

return [
  { json: { query_type: 'cx_posts', graphql_query: cx_query } },
  { json: { query_type: 'competitor_search', graphql_query: competitor_query } }
];

const items = $input.all();
const posts = [];

for (const item of items) {
  const edges = item.json && item.json.data && item.json.data.posts ? item.json.data.posts.edges : [];

  for (const edge of edges) {
    const node = edge.node;
    if (!node || !node.name) continue;

    const commentBodies = (node.comments && node.comments.edges ? node.comments.edges : [])
      .map(e => e.node && e.node.body ? e.node.body : '')
      .filter(Boolean)
      .join(' | ');

    posts.push({
      json: {
        title: node.name || '',
        body: [node.tagline, node.description, commentBodies].filter(Boolean).join(' '),
        url: node.url || '',
        author: '',
        subreddit: '',
        source: 'ProductHunt',
        ph_id: node.id || '',
        votes: node.votesCount || 0,
        comments_count: node.commentsCount || 0
      }
    });
  }
}

return posts;

const productTerms = [
  'nps', 'csat', 'ces', 'net promoter', 'customer satisfaction',
  'customer effort', 'survey tool', 'feedback tool', 'customer feedback tool',
  'in-app feedback', 'user feedback tool', 'voice of customer', 'voc',
  'churn survey', 'customer feedback', 'user feedback', 'collect feedback',
  'gather feedback', 'feedback from customers', 'feedback from users',
];

const competitorTerms = [
  'qualtrics', 'delighted', 'survicate', 'medallia', 'uservoice',
  'getsatisfaction', 'hotjar', 'intercom survey',
];

const broadFormTerms = ['typeform', 'form builder', 'forms'];

const painTerms = [
  'alternative', 'replace', 'replacement', 'switch', 'switching',
  'migrate', 'migration', 'pricing', 'expensive', 'cost', 'too complex',
  'hard to justify', 'recommend', 'what do you use', 'looking for',
  'anyone found', 'room to build', 'frustration', 'shut down', 'shutdown',
  'monetize', 'monetization',
];

const acronymTerms = ['nps', 'csat', 'ces', 'voc'];

function hasTerm(text, term) {
  if (acronymTerms.includes(term)) {
    return new RegExp('(^|[^a-z0-9])' + term + '([^a-z0-9]|$)', 'i').test(text);
  }
  return text.includes(term);
}

const items = $input.all();
const filtered = [];

for (const item of items) {
  const title = String(item.json.title || '').toLowerCase();
  const body = String(item.json.body || '').toLowerCase();
  const text = title + ' ' + body;

  const hasProduct = productTerms.some((term) => hasTerm(text, term));
  const hasCompetitor = competitorTerms.some((term) => hasTerm(text, term));
  const hasBroadForm = broadFormTerms.some((term) => hasTerm(text, term));
  const hasPain = painTerms.some((term) => hasTerm(text, term));

  if (hasProduct || hasCompetitor || (hasBroadForm && hasPain && hasProduct)) filtered.push(item);
}

return filtered;

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = {};
const ONE_DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
for (const url in staticData.seenUrls) {
  if (now - staticData.seenUrls[url] > ONE_DAY) delete staticData.seenUrls[url];
}
const items = $input.all();
const fresh = [];
for (const item of items) {
  const url = item.json.url;
  if (!url) continue;
  if (!staticData.seenUrls[url]) {
    staticData.seenUrls[url] = now;
    fresh.push(item);
  }
}
return fresh;

