const llmItems = $input.all();
const sourceItems = $('Dedup Static Memory').all();
const results = [];

function safeJsonParse(rawText) {
  const fence = String.fromCharCode(96, 96, 96);
  const cleaned = String(rawText || '')
    .replace(new RegExp(fence + 'json\\s*', 'gi'), '')
    .replace(new RegExp(fence + '\\s*', 'g'), '')
    .trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  return JSON.parse(cleaned.slice(start, end + 1));
}

for (let i = 0; i < llmItems.length; i++) {
  const item = llmItems[i];
  const source = sourceItems[i] ? sourceItems[i].json : {};
  const rawText = item.json.text || item.json.output || item.json.response || item.json.content || '';
  let parsed;
  try { parsed = safeJsonParse(rawText); } catch (_) { parsed = null; }
  if (!parsed || typeof parsed !== 'object') continue;

  results.push({
    json: {
      ...source,
      pain_point: String(parsed.pain_point || '').trim(),
      intent: String(parsed.intent || 'learning').trim().toLowerCase(),
      urgency: String(parsed.urgency || 'low').trim().toLowerCase(),
      tool_mentioned: parsed.tool_mentioned ? String(parsed.tool_mentioned).trim() : null,
      elvan_angle: String(parsed.elvan_angle || '').trim(),
      base_score: Number(parsed.score) || 1,
      draft_reply: String(parsed.draft_reply || '').trim(),
      llm_raw_output: String(rawText || ''),
    },
  });
}

return results;

const intentKeywords = [
  'alternative', 'replace', 'replacement', 'looking for',
  'recommend', 'switch', 'switching', 'what do you use',
  'anyone using', 'anyone tried', 'moved away', 'moved from',
  'migrated', 'shut down', 'shutdown', 'pricing', 'expensive',
  'cost-effective', 'hard to justify', 'room to build',
];

const competitorKeywords = [
  'delighted', 'qualtrics', 'survicate', 'medallia', 'uservoice',
  'getsatisfaction', 'hotjar', 'intercom',
];

const directCategoryKeywords = [
  'nps', 'csat', 'net promoter', 'customer feedback', 'feedback tool',
  'customer feedback tool', 'survey tool', 'customer satisfaction',
  'customer effort', 'voice of customer', 'in-app feedback',
];

const items = $input.all();
const results = [];

for (const item of items) {
  const title = item.json.title || '';
  const body = item.json.body || '';
  const base_score = item.json.base_score || 1;
  const text = (title + ' ' + body).toLowerCase();
  let boost = 0;
  if (intentKeywords.some((kw) => text.includes(kw))) boost += 2;
  if (competitorKeywords.some((kw) => text.includes(kw))) boost += 2;
  if (directCategoryKeywords.some((kw) => text.includes(kw))) boost += 1;

  const boosted_score = Math.max(0, Math.min(10, Number(base_score || 1) + boost));
  const tier = boosted_score >= 8 ? 'hot' : boosted_score >= 5 ? 'medium' : 'low';
  results.push({ json: { ...item.json, boosted_score, tier } });
}

return results;

const post = $json;
const normalizedSource = (() => {
  if (post.source === 'HackerNews') return 'hn';
  if (post.source === 'ProductHunt') return 'ph';
  return String(post.source || '').trim().toLowerCase();
})();
const canonicalUrl = String(post.url || '').trim();
const externalId = String(post.objectID || post.ph_id || canonicalUrl || '').trim();
const dedupeId = canonicalUrl || externalId;
const title = String(post.title || '').trim();
const priority = String(post.tier || 'low').trim().toLowerCase() || 'low';
const score = Number(post.boosted_score ?? post.base_score ?? 0);

if (!normalizedSource || !dedupeId || !title) throw new Error('Prep Neon Signal Row requires source, title, and URL/objectID/ph_id');
if (!['hot', 'medium', 'low'].includes(priority)) throw new Error('Invalid signal priority: ' + priority);

return {
  json: {
    dedupe_key: 'n8n:' + normalizedSource + ':' + dedupeId,
    source: normalizedSource,
    source_system: 'n8n',
    workflow: 'workflow1-hn-producthunt',
    external_id: externalId || null,
    title,
    body: String(post.body || '').trim() || null,
    url: canonicalUrl || null,
    author: String(post.author || '').trim() || null,
    subreddit: String(post.subreddit || '').trim() || null,
    intent: String(post.intent || 'learning').trim().toLowerCase() || 'learning',
    urgency: String(post.urgency || 'low').trim().toLowerCase() || 'low',
    priority,
    tool_mentioned: String(post.tool_mentioned || '').trim() || null,
    pain_point: String(post.pain_point || '').trim() || null,
    elvan_angle: String(post.elvan_angle || '').trim() || null,
    draft_reply: String(post.draft_reply || '').trim() || null,
    score,
    base_score: Number(post.base_score ?? 0),
    boosted_score: score,
    comments_count: Number(post.num_comments ?? post.comments_count ?? 0),
    upvotes: Number(post.points ?? post.votes ?? 0),
    alerted: false,
    hot_lead: priority === 'hot',
    occurred_at: post.created_at || new Date().toISOString()
  }
};

const checks = $input.all();
const preparedRows = $('Prep Neon Signal Row').all();
const fresh = [];
for (let i = 0; i < checks.length; i++) {
  const value = checks[i].json.exists;
  const exists = value === true || value === 'true' || value === 1 || value === '1';
  if (!exists && preparedRows[i]) fresh.push(preparedRows[i]);
}
return fresh;
